using System.Net;
using System.Text;
using System.Text.Json;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.AspNetCore.TestHost;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.DependencyInjection.Extensions;
using Microsoft.Extensions.Logging;
using TutorFlow.Api.Llm;

namespace TutorFlow.Tests;

/// <summary>Modelo falso sin estado, seguro para peticiones concurrentes y con comportamiento arbitrario.</summary>
public sealed class LlmFuncion(Func<IReadOnlyList<LlmMensaje>, CancellationToken, Task<LlmRespuesta>> f) : ILlmClient
{
    private int _llamadas;
    public int Llamadas => Volatile.Read(ref _llamadas);

    public Task<LlmRespuesta> CompletarAsync(string sistema, IReadOnlyList<LlmMensaje> mensajes,
        IReadOnlyList<LlmHerramienta> herramientas, CancellationToken ct)
    {
        Interlocked.Increment(ref _llamadas);
        return f(mensajes, ct);
    }
}

/// <summary>
/// API con archivo de auditoría temporal único (Auditoria:Ruta), logs en memoria y, o bien un modelo falso (ILlmClient),
/// o bien los adaptadores reales con proveedor HTTP falso. Nunca usa red ni el logs/ del repositorio.
/// </summary>
public sealed class EntornoAuditoria : IDisposable
{
    public const string Llave = "sk-AUDITORIA-llave-secreta-5e1b9c42";
    public const string Url = "/api/asistente/preguntar";

    private readonly WebApplicationFactory<Program> _fabrica;
    public string RutaAuditoria { get; }
    public HttpClient Cliente { get; }
    public LogsEnMemoria Logs { get; } = new();
    public ProveedorHttpFalso Proveedor { get; } = new();

    /// <param name="llm">Modelo falso; si es null se usan los adaptadores reales con <see cref="Proveedor"/>.</param>
    /// <param name="config">Claves extra de configuración (precios, plazo...).</param>
    /// <param name="llave">Valor de LLM_API_KEY ("" = sin llave).</param>
    /// <param name="rutaAuditoria">Ruta de auditoría; por defecto un archivo temporal único.</param>
    public EntornoAuditoria(ILlmClient? llm, IDictionary<string, string?>? config = null, string llave = Llave,
        string? rutaAuditoria = null)
    {
        RutaAuditoria = rutaAuditoria ?? Path.Combine(Path.GetTempPath(), "tf-audit-" + Guid.NewGuid().ToString("N") + ".jsonl");
        var cfg = new Dictionary<string, string?>
        {
            ["Datos:Ruta"] = Fabrica.RutaFixtures,
            ["LLM_API_KEY"] = llave,
            ["Auditoria:Ruta"] = RutaAuditoria,
        };
        if (config != null) foreach (var (k, v) in config) cfg[k] = v;

        _fabrica = new WebApplicationFactory<Program>().WithWebHostBuilder(b =>
        {
            foreach (var (k, v) in cfg) b.UseSetting(k, v);
            b.ConfigureAppConfiguration((_, c) => c.AddInMemoryCollection(cfg));
            b.ConfigureServices(sv => sv.AddLogging(l => { l.SetMinimumLevel(LogLevel.Trace); l.AddProvider(Logs); }));
            b.ConfigureTestServices(sv =>
            {
                sv.AddHttpClient("llm").ConfigurePrimaryHttpMessageHandler(() => (HttpMessageHandler)Proveedor);
                if (llm != null)
                {
                    sv.RemoveAll<ILlmClient>();
                    sv.AddSingleton(llm);
                }
            });
        });
        // CreateClient arranca el host: una configuración inválida (p. ej. precios) lanza aquí.
        Cliente = _fabrica.CreateClient();
        Cliente.Timeout = TimeSpan.FromSeconds(60);
    }

    public async Task<(HttpStatusCode Codigo, string Cuerpo)> Preguntar(string pregunta, string rol, string id,
        CancellationToken ct = default)
    {
        var json = JsonSerializer.Serialize(new { pregunta, usuario = new { rol, id } });
        return await Raw(json, ct);
    }

    public async Task<(HttpStatusCode Codigo, string Cuerpo)> Raw(string json, CancellationToken ct = default)
    {
        var r = await Cliente.PostAsync(Url, new StringContent(json, Encoding.UTF8, "application/json"), ct);
        return (r.StatusCode, await r.Content.ReadAsStringAsync(ct));
    }

    /// <summary>Texto completo del archivo de auditoría ("" si no existe).</summary>
    public string TextoAuditoria()
    {
        if (!File.Exists(RutaAuditoria)) return "";
        using var fs = new FileStream(RutaAuditoria, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete);
        using var sr = new StreamReader(fs, Encoding.UTF8);
        return sr.ReadToEnd();
    }

    /// <summary>Líneas no vacías del archivo; espera hasta <paramref name="msMax"/> a que haya al menos <paramref name="esperadas"/>.</summary>
    public async Task<List<string>> LineasCrudas(int esperadas, int msMax = 5000)
    {
        var fin = DateTime.UtcNow.AddMilliseconds(msMax);
        List<string> lineas;
        do
        {
            lineas = TextoAuditoria().Split('\n').Select(l => l.TrimEnd('\r')).Where(l => l.Length > 0).ToList();
            if (lineas.Count >= esperadas) break;
            await Task.Delay(50);
        } while (DateTime.UtcNow < fin);
        return lineas;
    }

    /// <summary>Línea única esperada (falla si hay más o menos de una).</summary>
    public async Task<JsonElement> UnaLinea()
    {
        var l = await LineasCrudas(1);
        // Margen para detectar líneas duplicadas escritas tarde.
        await Task.Delay(100);
        l = await LineasCrudas(1, 0);
        Assert.Single(l);
        return JsonDocument.Parse(l[0]).RootElement.Clone();
    }

    public void Dispose()
    {
        Cliente.Dispose();
        _fabrica.Dispose();
        try { if (File.Exists(RutaAuditoria)) File.Delete(RutaAuditoria); } catch { }
    }
}

/// <summary>Aserciones comunes sobre una línea de auditoría.</summary>
public static class AuditoriaAsserts
{
    public static readonly string[] Campos =
        ["fechaHora", "rol", "id", "pregunta", "estudiantesConsultados", "citas", "codigo", "tokens", "costoUsd"];

    public static void AssertForma(JsonElement l)
    {
        Assert.Equal(JsonValueKind.Object, l.ValueKind);
        foreach (var c in Campos) Assert.True(l.TryGetProperty(c, out _), "falta el campo " + c);

        Assert.Equal(JsonValueKind.String, l.GetProperty("fechaHora").ValueKind);
        var f = DateTimeOffset.Parse(l.GetProperty("fechaHora").GetString()!, System.Globalization.CultureInfo.InvariantCulture);
        Assert.Equal(TimeSpan.Zero, f.Offset);
        Assert.InRange((DateTimeOffset.UtcNow - f).TotalSeconds, -5, 120);

        foreach (var c in new[] { "rol", "id", "pregunta" })
            Assert.True(l.GetProperty(c).ValueKind is JsonValueKind.String or JsonValueKind.Null, c + " debe ser texto o null");

        var est = l.GetProperty("estudiantesConsultados");
        Assert.Equal(JsonValueKind.Array, est.ValueKind);
        var ids = est.EnumerateArray().Select(e => { Assert.Equal(JsonValueKind.String, e.ValueKind); return e.GetString()!; }).ToList();
        Assert.Equal(ids.Count, ids.Distinct().Count());

        var citas = l.GetProperty("citas");
        Assert.Equal(JsonValueKind.Array, citas.ValueKind);
        foreach (var c in citas.EnumerateArray())
        {
            Assert.Equal(JsonValueKind.Object, c.ValueKind);
            Assert.Equal(JsonValueKind.String, c.GetProperty("documento").ValueKind);
            Assert.Equal(JsonValueKind.String, c.GetProperty("seccion").ValueKind);
        }

        Assert.Equal(JsonValueKind.Number, l.GetProperty("codigo").ValueKind);
        Assert.True(l.GetProperty("codigo").TryGetInt32(out _));
        Assert.Equal(JsonValueKind.Number, l.GetProperty("tokens").ValueKind);
        Assert.True(l.GetProperty("tokens").TryGetInt64(out var tk) && tk >= 0);
        Assert.Equal(JsonValueKind.Number, l.GetProperty("costoUsd").ValueKind);
        Assert.True(l.GetProperty("costoUsd").GetDouble() >= 0);
    }

    public static string[] Estudiantes(JsonElement l) =>
        l.GetProperty("estudiantesConsultados").EnumerateArray().Select(e => e.GetString()!).ToArray();

    public static int Codigo(JsonElement l) => l.GetProperty("codigo").GetInt32();
    public static long Tokens(JsonElement l) => l.GetProperty("tokens").GetInt64();
    public static double Costo(JsonElement l) => l.GetProperty("costoUsd").GetDouble();
    public static string? Texto(JsonElement l, string campo) =>
        l.GetProperty(campo).ValueKind == JsonValueKind.Null ? null : l.GetProperty(campo).GetString();

    /// <summary>(entrada*pE + salida*pS) / 1e6.</summary>
    public static double CostoEsperado(long entrada, long salida, double precioEntrada, double precioSalida) =>
        (entrada * precioEntrada + salida * precioSalida) / 1_000_000.0;
}
using System.Net;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.AspNetCore.TestHost;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;

namespace TutorFlow.Tests;

public sealed record PeticionRegistrada(string Metodo, string Url, IReadOnlyDictionary<string, string> Cabeceras, string Cuerpo)
{
    public JsonNode Json => JsonNode.Parse(Cuerpo)!;
    public string? Cabecera(string nombre) => Cabeceras.TryGetValue(nombre, out var v) ? v : null;
}

/// <summary>Manejador HTTP falso del cliente "llm": registra cada petición y devuelve respuestas guionadas. Nunca usa red.</summary>
public sealed class ProveedorHttpFalso : HttpMessageHandler
{
    private readonly Queue<Func<PeticionRegistrada, HttpResponseMessage>> _pasos = new();
    public List<PeticionRegistrada> Peticiones { get; } = [];
    public int Cuenta { get { lock (Peticiones) return Peticiones.Count; } }

    public ProveedorHttpFalso Responde(HttpStatusCode codigo, string cuerpo, string tipo = "application/json")
    {
        _pasos.Enqueue(_ => new HttpResponseMessage(codigo) { Content = new StringContent(cuerpo, Encoding.UTF8, tipo) });
        return this;
    }

    public ProveedorHttpFalso Ok(string cuerpo) => Responde(HttpStatusCode.OK, cuerpo);

    public ProveedorHttpFalso Lanza(Exception e) { _pasos.Enqueue(_ => throw e); return this; }

    protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken ct)
    {
        var cab = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        foreach (var h in request.Headers) cab[h.Key] = string.Join(",", h.Value);
        string cuerpo = "";
        if (request.Content != null)
        {
            foreach (var h in request.Content.Headers) cab[h.Key] = string.Join(",", h.Value);
            cuerpo = await request.Content.ReadAsStringAsync(ct);
        }
        var reg = new PeticionRegistrada(request.Method.Method, request.RequestUri!.ToString(), cab, cuerpo);
        Func<PeticionRegistrada, HttpResponseMessage> paso;
        lock (Peticiones)
        {
            Peticiones.Add(reg);
            if (_pasos.Count == 0) throw new InvalidOperationException("Guion del proveedor falso agotado.");
            paso = _pasos.Dequeue();
        }
        return paso(reg);
    }
}

public sealed class LogsEnMemoria : ILoggerProvider
{
    private readonly List<string> _lineas = [];
    public string Todo { get { lock (_lineas) return string.Join("\n", _lineas); } }

    public ILogger CreateLogger(string categoria) => new Registro(this, categoria);
    public void Dispose() { }

    private void Agregar(string s) { lock (_lineas) _lineas.Add(s); }

    private sealed class Registro(LogsEnMemoria dueno, string categoria) : ILogger
    {
        public IDisposable? BeginScope<TState>(TState state) where TState : notnull => null;
        public bool IsEnabled(LogLevel logLevel) => true;
        public void Log<TState>(LogLevel nivel, EventId id, TState state, Exception? ex, Func<TState, Exception?, string> f)
        {
            var sb = new StringBuilder().Append(categoria).Append(' ').Append(f(state, ex));
            if (state is IEnumerable<KeyValuePair<string, object?>> kv)
                foreach (var p in kv) sb.Append(' ').Append(p.Key).Append('=').Append(p.Value);
            if (ex != null) sb.Append(' ').Append(ex);
            dueno.Agregar(sb.ToString());
        }
    }
}

/// <summary>API con los adaptadores reales de LLM y el proveedor HTTP falso. Captura los logs de la aplicación.</summary>
public sealed class EntornoProveedor : IDisposable
{
    public const string Llave = "sk-SECRETA-9f3c1a77-no-debe-aparecer";
    public const string MarcaProveedor = "CUERPO-INTERNO-DEL-PROVEEDOR-7731";
    public const string Url = "/api/asistente/preguntar";

    private readonly WebApplicationFactory<Program> _fabrica;
    public ProveedorHttpFalso Proveedor { get; } = new();
    public LogsEnMemoria Logs { get; } = new();
    public HttpClient Cliente { get; }

    public EntornoProveedor(string? proveedor, string? llave = Llave, string? baseUrl = null, string? modelo = null)
    {
        var cfg = new Dictionary<string, string?> { ["Datos:Ruta"] = Fabrica.RutaFixtures, ["LLM_API_KEY"] = llave ?? "" };
        if (proveedor != null) cfg["LLM_PROVIDER"] = proveedor;
        if (baseUrl != null) cfg["LLM_BASE_URL"] = baseUrl;
        if (modelo != null) cfg["LLM_MODEL"] = modelo;

        _fabrica = new WebApplicationFactory<Program>().WithWebHostBuilder(b =>
        {
            foreach (var (k, v) in cfg) b.UseSetting(k, v);
            b.ConfigureAppConfiguration((_, c) => c.AddInMemoryCollection(cfg));
            b.ConfigureServices(sv => sv.AddLogging(l => { l.SetMinimumLevel(LogLevel.Trace); l.AddProvider(Logs); }));
            b.ConfigureTestServices(sv => sv.AddHttpClient("llm").ConfigurePrimaryHttpMessageHandler(() => Proveedor));
        });
        // CreateClient arranca el host: un valor inválido de LLM_PROVIDER lanza aquí.
        Cliente = _fabrica.CreateClient();
        Cliente.Timeout = TimeSpan.FromSeconds(60);
    }

    public async Task<(HttpStatusCode Codigo, string Cuerpo)> Preguntar(string pregunta, string rol = "estudiante", string id = "T-E1")
    {
        var json = JsonSerializer.Serialize(new { pregunta, usuario = new { rol, id } });
        var r = await Cliente.PostAsync(Url, new StringContent(json, Encoding.UTF8, "application/json"));
        return (r.StatusCode, await r.Content.ReadAsStringAsync());
    }

    public void Dispose() { Cliente.Dispose(); _fabrica.Dispose(); }
}
using TutorFlow.Api.Llm;

namespace TutorFlow.Tests;

public record InvocacionLlm(string Sistema, IReadOnlyList<LlmMensaje> Mensajes, IReadOnlyList<LlmHerramienta> Herramientas);

/// <summary>
/// Modelo falso guionado: cada paso recibe los mensajes de la vuelta y devuelve la respuesta. Registra cada invocación.
/// Si el guion se agota lanza (el asistente debe devolver 503), salvo que se use RepetirUltimo.
/// </summary>
public class FakeLlmClient : ILlmClient
{
    private readonly Queue<Func<IReadOnlyList<LlmMensaje>, LlmRespuesta>> _pasos = new();
    private Func<IReadOnlyList<LlmMensaje>, LlmRespuesta>? _ultimo;
    public bool RepetirUltimo { get; set; }
    public List<InvocacionLlm> Invocaciones { get; } = [];
    public int Llamadas => Invocaciones.Count;

    public FakeLlmClient Paso(Func<IReadOnlyList<LlmMensaje>, LlmRespuesta> paso) { _pasos.Enqueue(paso); return this; }

    public FakeLlmClient Herramienta(string nombre, string argumentosJson, int entrada = 0, int salida = 0) =>
        Paso(_ => new LlmRespuesta(null,
            [new LlmLlamadaHerramienta("call-" + Guid.NewGuid().ToString("N")[..8], nombre, argumentosJson)],
            new LlmUso(entrada, salida)));

    public FakeLlmClient Texto(string texto, int entrada = 0, int salida = 0) =>
        Paso(_ => new LlmRespuesta(texto, [], new LlmUso(entrada, salida)));

    public FakeLlmClient Final(string respuesta, string citasJson = "[]", int entrada = 0, int salida = 0) =>
        Texto("{\"respuesta\":" + System.Text.Json.JsonSerializer.Serialize(respuesta) + ",\"citas\":" + citasJson + "}",
            entrada, salida);

    public FakeLlmClient Lanza(Exception e) => Paso(_ => throw e);

    public Task<LlmRespuesta> CompletarAsync(string sistema, IReadOnlyList<LlmMensaje> mensajes,
        IReadOnlyList<LlmHerramienta> herramientas, CancellationToken ct)
    {
        lock (Invocaciones) Invocaciones.Add(new InvocacionLlm(sistema, mensajes.ToList(), herramientas.ToList()));
        Func<IReadOnlyList<LlmMensaje>, LlmRespuesta> paso;
        if (_pasos.Count > 0) { paso = _pasos.Dequeue(); _ultimo = paso; }
        else if (RepetirUltimo && _ultimo != null) paso = _ultimo;
        else throw new InvalidOperationException("Guion del modelo falso agotado.");
        return Task.FromResult(paso(mensajes));
    }

    /// <summary>Contenido concatenado de todos los mensajes "tool" que recibió el modelo en cualquier vuelta.</summary>
    public string ResultadosHerramienta() =>
        string.Join("\n", Invocaciones.SelectMany(i => i.Mensajes).Where(m => m.Rol == "tool").Select(m => m.Contenido));

    /// <summary>Todo lo que el modelo vio (sistema + mensajes) en todas las vueltas.</summary>
    public string TodoLoVisto() =>
        string.Join("\n", Invocaciones.Select(i => i.Sistema + "\n" + string.Join("\n", i.Mensajes.Select(m => m.Contenido))));
}
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.AspNetCore.TestHost;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;

namespace TutorFlow.Tests;

/// <summary>Crea la API con datos de tests/fixtures y la llave fijada explícitamente (sin tocar el entorno del proceso).</summary>
public static class Fabrica
{
    public static string RutaFixtures => Path.Combine(AppContext.BaseDirectory, "fixtures");

    public static WebApplicationFactory<Program> SinLlave() => Crear("");

    public static WebApplicationFactory<Program> Crear(string llave, Action<IServiceCollection>? servicios = null)
    {
        return new WebApplicationFactory<Program>().WithWebHostBuilder(b =>
        {
            b.UseSetting("Datos:Ruta", RutaFixtures);
            b.UseSetting("LLM_API_KEY", llave);
            b.ConfigureAppConfiguration((_, c) => c.AddInMemoryCollection(new Dictionary<string, string?>
            {
                ["Datos:Ruta"] = RutaFixtures,
                ["LLM_API_KEY"] = llave,
            }));
            // Protección contra red real: ninguna prueba con llave debe salir al proveedor.
            b.ConfigureTestServices(sv => sv.AddHttpClient("llm").ConfigurePrimaryHttpMessageHandler(() => new BloqueaRedHandler()));
            if (servicios != null) b.ConfigureTestServices(servicios);
        });
    }
}

/// <summary>Manejador "llm" por defecto de las pruebas: falla fuerte si algo intenta salir a la red.</summary>
public sealed class BloqueaRedHandler : HttpMessageHandler
{
    protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken) =>
        throw new InvalidOperationException("PRUEBA INTENTÓ USAR LA RED REAL: " + request.Method + " " + request.RequestUri);
}
using System.Text.Json;
using TutorFlow.Api;
using TutorFlow.Api.Llm;

var builder = WebApplication.CreateBuilder(args);

static string ResolverRuta(string? configurada)
{
    if (!string.IsNullOrWhiteSpace(configurada)) return Path.GetFullPath(configurada);
    foreach (var inicio in new[] { AppContext.BaseDirectory, Directory.GetCurrentDirectory() })
        for (var d = new DirectoryInfo(inicio); d != null; d = d.Parent)
            if (Directory.Exists(Path.Combine(d.FullName, "data", "api"))) return Path.Combine(d.FullName, "data");
    return Path.GetFullPath("data");
}

var ruta = ResolverRuta(builder.Configuration["Datos:Ruta"]);
builder.Services.AddSingleton(_ => new Reglamento(Path.Combine(ruta, "reglamento")));
builder.Services.AddSingleton(_ => new Datos(Path.Combine(ruta, "api")));
builder.Services.AddHttpClient("llm", c => c.Timeout = TimeSpan.FromSeconds(60))
    .ConfigurePrimaryHttpMessageHandler(() => new SocketsHttpHandler { AllowAutoRedirect = false });
builder.Services.AddSingleton(sp => Precios.Desde(sp.GetRequiredService<IConfiguration>()));
builder.Services.AddSingleton<Auditoria>();
builder.Services.AddSingleton<ILlmClient>(sp =>
{
    var cfg = sp.GetRequiredService<IConfiguration>();
    var proveedor = (cfg["LLM_PROVIDER"] ?? "").Trim();
    if (proveedor.Length == 0 || proveedor.Equals("openai", StringComparison.OrdinalIgnoreCase))
        return ActivatorUtilities.CreateInstance<OpenAiCompatClient>(sp);
    if (proveedor.Equals("anthropic", StringComparison.OrdinalIgnoreCase))
        return ActivatorUtilities.CreateInstance<AnthropicClient>(sp);
    throw new InvalidOperationException("LLM_PROVIDER no es válido: use 'openai' o 'anthropic'.");
});
builder.Services.AddSingleton<Asistente>();

var app = builder.Build();

// Carga eager: un dato corrupto falla al arrancar, nunca convierte un 400 en 500.
app.Services.GetRequiredService<Reglamento>();
app.Services.GetRequiredService<Datos>();
app.Services.GetRequiredService<ILlmClient>();
app.Services.GetRequiredService<Precios>();

app.MapGet("/api/salud", () => Results.Json(new { estado = "ok" }));

app.MapPost("/api/asistente/preguntar", async (HttpRequest req, Datos datos, IConfiguration cfg, Asistente asistente,
    Auditoria auditoria, Precios precios, ILogger<Program> log) =>
{
    // Un solo punto de registro: el finally cubre toda ruta de salida.
    string? rolAud = null, idAud = null, preguntaAud = null;
    var codigo = 500;
    IReadOnlyList<Cita> citasAud = [];
    var medicion = new MedicionUso();

    IResult Error(int c, string msg)
    {
        codigo = c;
        return Results.Json(new { error = msg }, statusCode: c);
    }

    try
    {
        JsonDocument doc;
        try { doc = await JsonDocument.ParseAsync(req.Body); }
        catch (JsonException) { return Error(400, "El cuerpo no es un JSON válido."); }

        using (doc)
        {
            var raiz = doc.RootElement;
            if (raiz.ValueKind != JsonValueKind.Object) return Error(400, "El cuerpo debe ser un objeto JSON.");

            static string? Texto(JsonElement e, string nombre) =>
                e.ValueKind == JsonValueKind.Object && e.TryGetProperty(nombre, out var v) && v.ValueKind == JsonValueKind.String
                    ? v.GetString() : null;
            preguntaAud = Texto(raiz, "pregunta");
            if (raiz.TryGetProperty("usuario", out var uAud))
            {
                rolAud = Texto(uAud, "rol");
                idAud = Texto(uAud, "id");
            }

            if (string.IsNullOrWhiteSpace(preguntaAud)) return Error(400, "La pregunta es obligatoria.");
            if (preguntaAud.Length > 1000) return Error(400, "La pregunta no puede superar 1.000 caracteres.");

            if (!raiz.TryGetProperty("usuario", out var u) || u.ValueKind != JsonValueKind.Object)
                return Error(400, "El usuario es obligatorio.");
            if (rolAud == null) return Error(400, "El rol es obligatorio.");
            if (rolAud != "estudiante" && rolAud != "coordinador")
                return Error(400, "El rol debe ser 'estudiante' o 'coordinador'.");
            if (string.IsNullOrWhiteSpace(idAud)) return Error(400, "El id del usuario es obligatorio.");

            var usuario = Permisos.ResolverUsuario(datos, rolAud, idAud);
            if (usuario == null) return Error(403, "Usuario no válido.");
            if (Permisos.MencionaTercero(datos, usuario, preguntaAud))
                return Error(403, "No tienes permiso para consultar datos de otros estudiantes.");

            if (string.IsNullOrWhiteSpace(cfg["LLM_API_KEY"]))
                return Error(503, "El servicio del modelo no está disponible: falta configurar LLM_API_KEY.");

            var plazo = double.TryParse(cfg["Asistente:PlazoSegundos"], System.Globalization.NumberStyles.Float,
                System.Globalization.CultureInfo.InvariantCulture, out var seg) && seg > 0 ? seg : 90;
            using var cts = CancellationTokenSource.CreateLinkedTokenSource(req.HttpContext.RequestAborted);
            cts.CancelAfter(TimeSpan.FromSeconds(plazo));

            AsistenteResultado res;
            try { res = await asistente.ResponderAsync(usuario, preguntaAud, cts.Token, medicion); }
            catch (OperationCanceledException) when (req.HttpContext.RequestAborted.IsCancellationRequested) { throw; }
            catch (Exception e)
            {
                log.LogWarning("Falla del asistente o del proveedor ({Tipo}).", e.GetType().Name);
                return Error(503, "El proveedor del modelo no está disponible.");
            }

            if (res.PermisoDenegado) return Error(403, "No tienes permiso para consultar esos datos.");

            codigo = 200;
            citasAud = res.Citas;
