            ["type"] = "message", ["role"] = "assistant", ["stop_reason"] = "end_turn",
            ["content"] = new JsonArray(new JsonObject { ["type"] = "text", ["text"] = FinalJson }),
            ["usage"] = new JsonObject { ["input_tokens"] = 9, ["output_tokens"] = 1 },
        }.ToJsonString();
