    private static IDictionary<string, string?> Cfg(string? proveedor, string pe = "1", string ps = "2")
    {
        var d = new Dictionary<string, string?> { ["LLM_PRECIO_ENTRADA_MTOK"] = pe, ["LLM_PRECIO_SALIDA_MTOK"] = ps };
