                + (usoOpenAi.Length > 0 ? ",\"usage\":" + usoOpenAi : "") + "}"
            : "{\"type\":\"message\",\"role\":\"assistant\",\"stop_reason\":\"end_turn\",\"content\":[{\"type\":\"text\",\"text\":\""
