        var (c, b) = await e.Preguntar("¿Cuál es la nota mínima?", "estudiante", "T-E1");
        sw.Stop();

        Assert.Equal(HttpStatusCode.OK, c);
        Assert.True(sw.Elapsed < TimeSpan.FromSeconds(2), "tardó " + sw.Elapsed);
